source='''def transform(grid):
    """Mark full separator rows and columns with color 2."""
    h, w = len(grid), len(grid[0])
    # ARC separators are full lines of a shared color.
    line_colors = {}
    for row in grid:
        if all(v == row[0] for v in row):
            line_colors[row[0]] = line_colors.get(row[0], 0) + 1
    for c in range(w):
        value = grid[0][c]
        if all(grid[r][c] == value for r in range(h)):
            line_colors[value] = line_colors.get(value, 0) + 1
    if not line_colors:
        return [row[:] for row in grid]
    sep = max(line_colors, key=line_colors.get)
    full_rows = {r for r in range(h) if all(v == sep for v in grid[r])}
    full_cols = {c for c in range(w) if all(grid[r][c] == sep for r in range(h))}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r in full_rows or c in full_cols:
                out[r][c] = 2
    return out
